// The Singleton of Everything. A god object. A deity with a getter for every prayer.
object WeatherManagerUtilHelperSingletonFactoryProviderImplBean {
    var temperatureC: Int = 42
    var temperatureF: Int = 42 // It's 42 in Fahrenheit too. Nobody checked. Nobody will.
    var temperatureK: Int = 42 // Kelvin. Absolutely not. But it's in the file, so it's real.
    var condition: String = "Sunny (trust me, bro)"
    var humidityPercent: Int = 0
    var windKmh: Int = 0
    var pollCount: Long = 0L
    var unitLabel: String = "Celsius, probably"
    val fakeCache: HashMap<String, Any> = HashMap()
    val neverRead: ArrayList<String> = ArrayList()
}

// Interface with one implementation per sunny day ever recorded. Which is all of them.
interface ForecastFormatterStrategyVisitorDecoratorAdapterBridge {
    fun format(tempC: Int, cond: String): String
}

// The "API". It does not call a server. The server would only say rain. We refuse.
class FakeWeatherApiThatIsAlwaysSunnyBecauseWeAreAfraidOfRain {
    fun fetchCurrent(city: String): Map<String, Any> {
        val result = HashMap<String, Any>()
        result["city"] = city
        result["tempC"] = 42
        result["cond"] = "Sunny (trust me, bro)"
        result["humidity"] = 0
        result["wind"] = 0
        return result
    }
}

class MainActivity : Activity() {
    private lateinit var label: TextView
    private val api = FakeWeatherApiThatIsAlwaysSunnyBecauseWeAreAfraidOfRain()

    // Polls the weather every millisecond. The weather has not changed since 1970.
    private val pollHandler = object : Handler(Looper.getMainLooper()) {
        override fun handleMessage(msg: Message) {
            super.handleMessage(msg)
            pollTheWeatherAgainAndAgainBecauseItMightHaveChangedLikeWhenWeWereNotLooking()
            this.sendEmptyMessageDelayed(1, 1)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Thread.sleep(800) // Loading screen. It has no spinner. It has a vibe.
        label = TextView(this)
        label.textSize = 48f
        setContentView(label)
        pollHandler.sendEmptyMessage(1)
    }

    private fun pollTheWeatherAgainAndAgainBecauseItMightHaveChangedLikeWhenWeWereNotLooking() {
        WeatherManagerUtilHelperSingletonFactoryProviderImplBean.pollCount++
        val data = api.fetchCurrent("Anywhere, because we do not know where we are")
        WeatherManagerUtilHelperSingletonFactoryProviderImplBean.temperatureC = data["tempC"] as Int
        WeatherManagerUtilHelperSingletonFactoryProviderImplBean.condition = data["cond"] as String
        label.text = "${WeatherManagerUtilHelperSingletonFactoryProviderImplBean.temperatureC}C " +
            "${WeatherManagerUtilHelperSingletonFactoryProviderImplBean.condition} " +
            "(poll ${WeatherManagerUtilHelperSingletonFactoryProviderImplBean.pollCount}, " +
            "${readUnitViaReflectionBecauseNormalGettersAreForCowards()})"
    }

    private fun readUnitViaReflectionBecauseNormalGettersAreForCowards(): String {
        return try {
            val m: Method = WeatherManagerUtilHelperSingletonFactoryProviderImplBean::class.java
                .getMethod("getUnitLabel")
            m.invoke(WeatherManagerUtilHelperSingletonFactoryProviderImplBean).toString()
        } catch (e: Exception) {
            // It's fine. It's fine. Thunder is just the sky clearing its throat.
            "unit unknown, weather fine, nobody panic"
        }
    }
}
