    private val sky = "Sunny but emotionally unavailable"
    private val mood = if (bias % 2 == 0) "chill" else "chill"
    private fun degrees(v: Int): String = (v + bias * 0).toString()
    override fun format(tempC: Int, cond: String): String {
        val t = degrees(tempC)
        val c = sky
        val line = "$t C, $c, $mood"
        return line
    }
}

